<?php
require_once 'layout.php'; admin_require_login(); require_once '../includes/db_connect.php'; $notice = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $companyId = filter_input(INPUT_POST, 'company_id', FILTER_VALIDATE_INT); $companyName = trim($_POST['company_name'] ?? ''); $package = trim($_POST['package'] ?? ''); $description = trim($_POST['description'] ?? ''); $eligibility = trim($_POST['eligibility'] ?? ''); $date = $_POST['drive_date'] ?? ''; $status = $_POST['status'] ?? 'upcoming';
    if (!$companyId && $companyName) { $stmt = $conn->prepare('INSERT INTO company (name, package, description) VALUES (?, ?, ?)'); $stmt->bind_param('sss', $companyName, $package, $description); if ($stmt->execute()) $companyId = $conn->insert_id; else $error = 'Could not create the company.'; }
    if (!$error && (!$companyId || !$date || !$eligibility)) $error = 'Choose or create a company, then complete the drive date and eligibility.';
    if (!$error) { $stmt = $conn->prepare('INSERT INTO drive (company_id, eligibility, drive_date, status) VALUES (?, ?, ?, ?)'); $stmt->bind_param('isss', $companyId, $eligibility, $date, $status); if ($stmt->execute()) $notice = 'Company drive created successfully.'; else $error = 'Could not save the drive.'; }
}
$companies = $conn->query('SELECT company_id, name FROM company ORDER BY name'); $drives = $conn->query('SELECT d.*, c.name, c.package FROM drive d JOIN company c ON c.company_id = d.company_id ORDER BY d.drive_date DESC'); admin_page_start('Companies & drives', 'drives'); ?>
<section class="page-heading"><h1>Companies & recruitment drives</h1><p>Add a new company on the fly or attach a new drive to an existing partner.</p></section>
<section class="card portal-card"><?php if ($notice): ?><p class="success"><?= htmlspecialchars($notice) ?></p><?php endif; ?><?php if ($error): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post" class="form-grid"><div class="field"><label for="company_id">Existing company</label><select id="company_id" name="company_id"><option value="">Create a new company below</option><?php while ($company = $companies->fetch_assoc()): ?><option value="<?= (int)$company['company_id'] ?>"><?= htmlspecialchars($company['name']) ?></option><?php endwhile; ?></select></div><div class="field"><label for="company_name">New company name</label><input id="company_name" name="company_name" placeholder="Leave blank when selecting existing"></div><div class="field"><label for="package">Package</label><input id="package" name="package" placeholder="e.g. 8 LPA"></div><div class="field"><label for="drive_date">Drive date</label><input id="drive_date" type="date" name="drive_date" required></div><div class="field full"><label for="description">Company description</label><textarea id="description" name="description" placeholder="Optional for an existing company"></textarea></div><div class="field"><label for="eligibility">Eligibility criteria</label><input id="eligibility" name="eligibility" required placeholder="e.g. CGPA 7.0+, branches: CSE/IT"></div><div class="field"><label for="status">Drive status</label><select id="status" name="status"><option value="upcoming">Upcoming</option><option value="closed">Closed</option></select></div><div class="full"><button class="btn" type="submit">Save recruitment drive</button></div></form></section>
<section class="card portal-card drive-list"><h2>Current drives</h2><?php while ($drive = $drives->fetch_assoc()): ?><div class="drive-item"><div><strong><?= htmlspecialchars($drive['name']) ?></strong><p class="help"><?= htmlspecialchars($drive['drive_date']) ?> · <?= htmlspecialchars($drive['eligibility']) ?></p></div><span class="status-badge"><?= htmlspecialchars(ucfirst($drive['status'])) ?></span></div><?php endwhile; ?></section><?php admin_page_end(); ?>
